const stack = [];
function use(fn) { stack.push(fn); }
function run(ctx, final) {
  let i = 0;
  function next(err) {
    while (i < stack.length) {
      const mw = stack[i];
      if (err) {
        if (mw.length === 4) { i++; mw(err, ctx, {}, next); return; }
        i++; continue;
      }
      if (mw.length === 4) { i++; continue; }
      i++;
      try { mw(ctx, next); } catch (e) { next(e); }
      return;
    }
    if (err) { ctx.log.push('FATAL:' + err.message); return; }
    final(ctx);
  }
  next();
}
use((c, nx) => { c.log.push('A in'); nx(); c.log.push('A out'); });
